mapper.select:
select oper_id, tenant_id, title, business_type, method, request_method, operator_type, oper_name, dept_name, oper_url, oper_ip, oper_param, json_result, status, error_msg, oper_time from sys_oper_log
AND title like concat('%', #{title}, '%')
AND business_type = #{businessType}
AND oper_name like concat('%', #{operName}, '%')
AND status = #{status}
order by oper_time desc
